// Service Worker for aggressive image caching
const CACHE_NAME = 'remote-slider-images-v1';
const IMAGE_CACHE_MAX_AGE = 7 * 24 * 60 * 60 * 1000; // 7 days

self.addEventListener('install', (event) => {
  self.skipWaiting();
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys().then((cacheNames) => {
      return Promise.all(
        cacheNames
          .filter((name) => name.startsWith('remote-slider-images-') && name !== CACHE_NAME)
          .map((name) => caches.delete(name))
      );
    })
  );
  return self.clients.claim();
});

self.addEventListener('fetch', (event) => {
  const { request } = event;
  const url = new URL(request.url);

  const isImage =
    url.hostname.includes('cloudinary.com') ||
    url.hostname.includes('sharkninja.com') ||
    /\\.(jpg|jpeg|png|gif|webp|svg)$/i.test(url.pathname);

  if (!isImage || request.method !== 'GET') {
    return;
  }

  event.respondWith(
    caches.open(CACHE_NAME).then((cache) => {
      return cache.match(request).then((cachedResponse) => {
        if (cachedResponse) {
          const cachedDate = new Date(cachedResponse.headers.get('date') || 0);
          const now = Date.now();
          if (now - cachedDate.getTime() < IMAGE_CACHE_MAX_AGE) {
            return cachedResponse;
          }
        }

        return fetch(request)
          .then((response) => {
            if (response && response.status === 200) {
              const responseToCache = response.clone();
              cache.put(request, responseToCache);
            }
            return response;
          })
          .catch(() => {
            return cachedResponse || new Response('Image not available', { status: 404 });
          });
      });
    })
  );
});
